var a=[{title:`Escolher um intervalo de repetições`,text:`Escolha um exercício, um número de séries e um intervalo, por exemplo três séries de 8–12 repetições. Comece com um peso que lhe permita chegar ao limite inferior do intervalo com técnica estável e algumas repetições de reserva. O intervalo não tem de ser 8–12. O seu objetivo e o exercício definem os limites.`},{title:`Merecer o aumento de carga`,text:`Primeiro, faça mais repetições boas com o mesmo peso ao longo de várias sessões. Quando todas as séries chegarem ao limite superior do intervalo com o esforço que planeou, acrescente o menor aumento de peso de que dispõe. As suas repetições costumam descer de novo para o limite inferior e o ciclo recomeça.`},{title:`Exemplo`,text:`Semana 1: remadas com haltere de 12 kg com 10, 9, 8. Semana 2: 11, 10, 9. Semana 3: 12, 12, 12 com controlo estável. Semana 4: experimente 14 kg com 9, 8, 8, se conseguir lidar com esse salto com boa execução. Estes números mostram como pode correr. Não tem de melhorar todas as semanas.`},{title:`Quando adaptar a regra`,text:`Um grande salto de peso pode ser demasiado difícil, sobretudo para músculos pequenos ou com equipamento doméstico limitado. Nesse caso, mantenha a carga atual, aumente o total de repetições ou escolha uma variação intermédia. Se uma sessão parecer invulgarmente cansativa, repita o último objetivo e deixe a progressão para mais tarde. O progresso real costuma ter altos e baixos.`},{title:`Usar o TrainUp`,text:`O seu plano dá a cada exercício séries e um objetivo de repetições e, durante um treino, regista as repetições que conclui em cada série. O TrainUp não prescreve pesos, por isso decide você quando acrescentar carga. Quando chegar ao limite superior do intervalo em todas as séries, verifique o seu RPE e a sua técnica antes de passar a um peso mais pesado.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: segurança e fundamentos do treino de resistência`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: técnica de treino com pesos (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:a,sources:s};export{r as default,a as sections,s as sources};